CREATE OR REPLACE FUNCTION public.efg_coach_pilot_entry_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_uid uuid := auth.uid();
 v_org uuid;
 v_coach uuid;
 v_receipt boolean := false;
 v_sharing boolean := false;
 v_intake public.efg_coach_relaunch_intakes%rowtype;
 v_plan public.efg_student_plan_access%rowtype;
 v_guide_goal uuid;
 v_guide_at timestamptz;
 v_guide jsonb;
 v_goal_ok boolean := false;
 v_follow_up boolean := false;
 v_route text := 'verify';
 v_current_legal_count integer := 0;
begin
 -- This routine reads only rows belonging to auth.uid(); never take a
 -- student, coach or organization id as a browser-supplied parameter.
 if v_uid is null then
  return pg_catalog.jsonb_build_object('route','verify','can_log_meals',false);
 end if;
 select p.organization_id,o.coach_id into v_org,v_coach
 from public.efg_profiles p
 join public.efg_organizations o on o.id=p.organization_id
 where p.user_id=v_uid and p.role='student' and p.active=true
   and o.coach_id is not null;
 if v_org is null or v_coach is null then
  return pg_catalog.jsonb_build_object('route','verify','can_log_meals',false);
 end if;
 -- Legal readiness is server-owned, not a browser-side checklist.
 -- An absent/unreviewed/replaced terms or privacy document blocks ALL routes,
 -- including already published student goals, without erasing historic data.
 select count(*) into v_current_legal_count
 from public.efg_legal_current_status() as doc where doc.accepted;
 if v_current_legal_count<>2 then
  return pg_catalog.jsonb_build_object(
    'route','legal','can_log_meals',false,
    'required_intake_version','coach_major_2026_r1',
    'required_pilot_version','coach_pilot_2026_demo1',
    'participation_confirmed',false,'general_intake_shared',false,
    'legal_current_accepted',false,
    'requires_separate_health_consent',true
  );
 end if;
 select exists(
  select 1 from public.efg_pilot_participation_receipts r
  where r.student_id=v_uid and r.organization_id=v_org
   and r.version='coach_pilot_2026_demo1'
   and r.acceptance_method='two_explicit_checkboxes'
   and r.participation_accepted=true
   and r.accepted_at is not null and r.revoked_at is null
 ) into v_receipt;
 if not v_receipt then
  v_route:='participation';
 else
  -- A prior shared intake never authorizes current coach access after
  -- the independent pilot sharing receipt is changed to FALSE.
  select exists(
   select 1 from public.efg_pilot_participation_receipts r
   where r.student_id=v_uid and r.organization_id=v_org
     and r.version='coach_pilot_2026_demo1'
     and r.participation_accepted and r.sharing_accepted
     and r.revoked_at is null
  ) into v_sharing;
  select exists(select 1 from public.efg_consents c
    where c.student_id=v_uid and c.organization_id=v_org and c.accepted=true)
    into v_follow_up;
  select i.* into v_intake from public.efg_coach_relaunch_intakes i
   where i.student_id=v_uid and i.organization_id=v_org
     and i.completed_version='coach_major_2026_r1';
  if not found then
   v_route:='intake';
  elsif v_intake.objective is null or v_intake.age_years is null
     or v_intake.height_cm is null or v_intake.weight_kg is null
     or v_intake.activity_level is null or v_intake.dietary_pattern is null then
   v_route:='intake'; -- Incomplete or cleared intake cannot unlock daily logging.
  elsif v_intake.shared_at is null or not v_follow_up or not v_sharing then
   v_route:='private'; -- Own current intake saved, without coach sharing.
  else
   v_route:='review';
   select a.* into v_plan from public.efg_student_plan_access a
    where a.student_id=v_uid and a.organization_id=v_org
      and a.coach_id=v_coach;
   if found and v_plan.status='published'
     and v_plan.published_goal_id is not null
     and v_plan.published_at >= v_intake.updated_at
     and v_plan.published_by=v_coach then
    select f.guided_goal_id,f.guided_plan_approved_at,f.guided_plan
     into v_guide_goal,v_guide_at,v_guide
     from public.efg_food_plans f
     where f.student_id=v_uid and f.coach_id=v_coach;
    select exists(select 1 from public.efg_goals g
       where g.id=v_plan.published_goal_id and g.student_id=v_uid
         and g.approved_by=v_coach)
      into v_goal_ok;
    if v_goal_ok and v_guide_goal=v_plan.published_goal_id
      and v_guide_at is not null and v_guide_at>=v_intake.updated_at
      and (case
     when pg_catalog.jsonb_typeof(v_guide->'meals')='array' then (
      (v_guide->>'kind'='five_meal_example' and v_guide->>'version'='1'
        and pg_catalog.jsonb_array_length(v_guide->'meals')=5)
      or
      (v_guide->>'kind'='flexible_meal_guide' and v_guide->>'version'='2'
        and pg_catalog.jsonb_array_length(v_guide->'meals') between 2 and 6)
     ) else false
    end) then
      v_route:='ready';
    end if;
   end if;
  end if;
 end if;
 return pg_catalog.jsonb_build_object(
  'route',v_route,'can_log_meals',v_route='ready',
  'required_intake_version','coach_major_2026_r1',
  'required_pilot_version','coach_pilot_2026_demo1',
  'participation_confirmed',v_receipt,
  'general_intake_shared',v_intake.shared_at is not null and v_follow_up and v_sharing,
  'legal_current_accepted',true,
  'requires_separate_health_consent',true
 );
end;
$function$

CREATE OR REPLACE FUNCTION public.efg_publish_coach_plan_draft_atomic(p_student uuid, p_expected_revision bigint, p_request_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_coach uuid:=auth.uid();
 v_org uuid;
 v_enabled boolean:=false;
 v_intake public.efg_coach_relaunch_intakes%rowtype;
 v_draft public.efg_coach_plan_drafts%rowtype;
 v_goal jsonb;
 v_guide jsonb;
 v_goal_id uuid;
 v_existing public.efg_coach_plan_publish_receipts%rowtype;
 v_food_ids text[];
 v_legal_count integer:=0;
 v_key text;
 v_value numeric;
 v_slot_count integer;
 v_distinct_slots integer;
begin
 select enabled into v_enabled from efg_private.coach_release_switches
 where switch_key='pilot_coach_atomic_publication';
 if v_enabled is distinct from true then
  raise exception 'Coach atomic publication has not been activated'
   using errcode='42501';
 end if;
 if v_coach is null or p_student is null or p_request_id is null or
  p_expected_revision is null or p_expected_revision<1 or
  not efg_private.coach_has_student(p_student) then
  raise exception 'Invalid or unauthorized Coach publication'
   using errcode='42501';
 end if;

 -- Student-scoped lock makes two devices and retries serialize.
 select a.organization_id into v_org
 from public.efg_student_plan_access a
 join public.efg_profiles p on p.user_id=a.student_id
 join public.efg_organizations o on o.id=p.organization_id
 where a.student_id=p_student and a.coach_id=v_coach
  and p.organization_id=a.organization_id and p.active and p.role='student'
  and o.coach_id=v_coach
 for update of a;
 if not found then
  raise exception 'Student is no longer assigned to this Coach'
   using errcode='42501';
 end if;

 -- The student's two unsigned-inferable pilot checkboxes and follow-up consent
 -- must still be valid. No acceptance is inferred from historical data.
 perform 1 from public.efg_pilot_participation_receipts r
 where r.student_id=p_student and r.organization_id=v_org
  and r.version='coach_pilot_2026_demo1'
  and r.acceptance_method='two_explicit_checkboxes'
  and r.participation_accepted and r.sharing_accepted
  and r.accepted_at is not null and r.revoked_at is null
 for share;
 if not found then raise exception 'Pilot participation/sharing missing or revoked'
   using errcode='42501'; end if;
 perform 1 from public.efg_consents c
 where c.student_id=p_student and c.organization_id=v_org and c.accepted
 for share;
 if not found then raise exception 'Coach follow-up consent missing or revoked'
   using errcode='42501'; end if;

 select i.* into v_intake from public.efg_coach_relaunch_intakes i
 where i.student_id=p_student and i.organization_id=v_org
  and i.completed_version='coach_major_2026_r1' and i.shared_at is not null
 for update of i;
 if not found then raise exception 'Current general intake not shared'
  using errcode='42501'; end if;
 -- The signed atomic RPC also enforces required nutrition fields. Neither a
 -- legacy shared_at timestamp nor a previously valid browser is sufficient.
 if v_intake.objective is null or v_intake.age_years is null
  or v_intake.height_cm is null or v_intake.weight_kg is null
  or v_intake.activity_level is null or v_intake.dietary_pattern is null then
  raise exception 'NCC: current shared nutrition intake incomplete'
   using errcode='42501';
 end if;

 -- Require BOTH distinct document kinds (not two accepted copies of Terms).
 -- ALL CURRENT text versions must be cryptographically verifiable and accepted
 -- separately by both student and Coach. Never mistake these for medical consent.
 select pg_catalog.count(distinct d.kind) into v_legal_count
 from public.efg_legal_documents d
 join public.efg_legal_acceptances student_rec
  on student_rec.document_id=d.id and student_rec.user_id=p_student
 join public.efg_legal_acceptances coach_rec
  on coach_rec.document_id=d.id and coach_rec.user_id=v_coach
 where d.is_current and d.published_at is not null
  and d.kind in ('terms','privacy')
  and d.sha256=pg_catalog.encode(
   pg_catalog.sha256(pg_catalog.convert_to(d.body,'UTF8')),'hex');
 if v_legal_count<>2 then
  raise exception 'Current Terms and Privacy not explicitly accepted by both parties'
   using errcode='42501'; end if;

 -- Only a matching Coach-owned draft at the latest intake revision can publish.
 select draft.* into v_draft
 from public.efg_coach_plan_drafts draft
 where draft.student_id=p_student and draft.coach_id=v_coach
  and draft.organization_id=v_org
 for update of draft;
 if not found or v_draft.source_intake_updated_at is distinct from v_intake.updated_at
  or v_draft.source_intake_revision is distinct from v_intake.revision then
  raise exception 'Draft based on old or missing intake'
   using errcode='PT409'; end if;

 -- Idempotent retries with same signed Coach/Student/revision are harmless.
 select receipt.* into v_existing from public.efg_coach_plan_publish_receipts receipt
 where receipt.request_id=p_request_id;
 if found then
  if v_existing.student_id is distinct from p_student or
    v_existing.coach_id is distinct from v_coach or
    v_existing.organization_id is distinct from v_org or
    v_existing.draft_revision is distinct from p_expected_revision then
   raise exception 'Publication key reused with different owner/revision'
    using errcode='23505'; end if;
  return v_existing.goal_id;
 end if;
 if v_draft.status<>'draft' or v_draft.draft_revision<>p_expected_revision then
  raise exception 'Draft revision no longer publishable'
   using errcode='PT409'; end if;

 v_goal:=v_draft.goal_proposal;
 v_guide:=v_draft.guide_proposal;
 if pg_catalog.jsonb_typeof(v_goal) is distinct from 'object'
  or v_goal->>'goal_type' not in ('fat_loss','recomp','muscle_gain','maintenance')
  or pg_catalog.jsonb_typeof(v_guide) is distinct from 'object'
  or pg_catalog.jsonb_typeof(v_guide->'meals') is distinct from 'array'
  or not (
    (v_guide->>'kind'='five_meal_example' and v_guide->>'version'='1'
      and pg_catalog.jsonb_array_length(v_guide->'meals')=5)
    or
    (v_guide->>'kind'='flexible_meal_guide' and v_guide->>'version'='2'
      and pg_catalog.jsonb_array_length(v_guide->'meals') between 2 and 6)
  ) then
  raise exception 'Goal or versioned Dieta Guia missing or invalid' using errcode='22023';
 end if;
 foreach v_key in array array['kcal','protein_g','carb_g','fat_g','fiber_g'] loop
  if pg_catalog.jsonb_typeof(v_goal->v_key) is distinct from 'number' then
   raise exception 'Missing numeric goal field %',v_key using errcode='22023'; end if;
  v_value:=(v_goal->>v_key)::numeric;
  if v_value<>pg_catalog.trunc(v_value) or
   v_value < (case when v_key='kcal' then 1200 else 0 end) or
   v_value > (case v_key when 'kcal' then 10000 when 'carb_g' then 2000
      when 'fiber_g' then 150 else 1000 end) then
   raise exception 'Goal field out of range %',v_key using errcode='22023';
  end if;
 end loop;
 select count(*),count(distinct meal.value->>'slot')
  into v_slot_count,v_distinct_slots
 from pg_catalog.jsonb_array_elements(v_guide->'meals') as meal(value);
 if v_slot_count<>pg_catalog.jsonb_array_length(v_guide->'meals')
   or v_distinct_slots<>v_slot_count or
   efg_private.coach_guide_foods_verified(v_guide) is distinct from true then
  raise exception 'Guide foods are not independently reviewed and current'
   using errcode='42501';
 end if;
 -- Verify the guide's nutrient references only. The food catalog for a
 -- student's diary is unchanged and never restricted by this reference set.
 v_food_ids:=efg_private.coach119_reviewed_food_ids(v_guide);

 -- The private transaction marker, not the client-settable GUC alone,
 -- authorizes suppression. Verify spoofing and rollback in isolated staging.
 -- Only after every check do legacy notices suppress, for this transaction ONLY.
 insert into efg_private.coach119_atomic_transactions(txid,coach_id)
 values(pg_catalog.txid_current(),v_coach);
 perform pg_catalog.set_config('efg.coach_atomic_publish','on',true);
 insert into public.efg_goals(
  student_id,approved_by,goal_type,kcal,protein_g,carb_g,fat_g,fiber_g,
  start_on,approved_at
 ) values(
  p_student,v_coach,v_goal->>'goal_type',
  (v_goal->>'kcal')::integer,(v_goal->>'protein_g')::integer,
  (v_goal->>'carb_g')::integer,(v_goal->>'fat_g')::integer,
  (v_goal->>'fiber_g')::integer,
  (pg_catalog.now() at time zone 'America/Argentina/Buenos_Aires')::date,
  pg_catalog.clock_timestamp()
 ) returning id into v_goal_id;

 insert into public.efg_food_plans(
  student_id,coach_id,approved_food_ids,updated_at,
  guided_plan,guided_goal_id,guided_plan_approved_at
 ) values(
  p_student,v_coach,v_food_ids,pg_catalog.clock_timestamp(),
  v_guide,v_goal_id,pg_catalog.clock_timestamp()
 )
 on conflict(student_id) do update set
  coach_id=excluded.coach_id,
  -- Store the versioned guide's nutrient reference IDs for source audit.
  -- This is not a per-student catalog filter. The BEFORE UPDATE trigger
  -- archives the previous guide and reference set for history.
  approved_food_ids=excluded.approved_food_ids,
  guided_plan=excluded.guided_plan,guided_goal_id=excluded.guided_goal_id,
  guided_plan_approved_at=excluded.guided_plan_approved_at,
  updated_at=excluded.updated_at;

 update public.efg_student_plan_access
 set status='published',published_goal_id=v_goal_id,
  published_at=pg_catalog.clock_timestamp(),published_by=v_coach,
  updated_at=pg_catalog.clock_timestamp()
 where student_id=p_student and organization_id=v_org and coach_id=v_coach;
 if not found then raise exception 'Student access changed mid-publication'
  using errcode='PT409'; end if;

 insert into public.efg_notifications(
  recipient_id,actor_id,kind,event_key,title,body,target_tab,target_student
 ) values(
  p_student,v_coach,'plan_update','coach_plan:'||v_goal_id::text,
  'Tu guía está lista','Tu coach aprobó tu nuevo objetivo y guía de alimentación.','home',p_student
 ) on conflict(recipient_id,event_key) do nothing;

 insert into public.efg_coach_plan_publish_receipts(
  request_id,student_id,organization_id,coach_id,draft_revision,goal_id
 ) values(p_request_id,p_student,v_org,v_coach,p_expected_revision,v_goal_id);

 update public.efg_coach_plan_drafts
 set status='published',updated_at=pg_catalog.clock_timestamp()
 where student_id=p_student and coach_id=v_coach and organization_id=v_org
  and draft_revision=p_expected_revision and status='draft';
 if not found then raise exception 'Concurrent draft change' using errcode='PT409'; end if;
 delete from efg_private.coach119_atomic_transactions
 where txid=pg_catalog.txid_current() and coach_id=v_coach;
 perform pg_catalog.set_config('efg.coach_atomic_publish','off',true);
 return v_goal_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.efg_save_coach_plan_draft(p_student uuid, p_goal jsonb, p_guide jsonb, p_intake_updated_at timestamp with time zone, p_intake_revision integer, p_expected_revision bigint DEFAULT NULL::bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_coach uuid := auth.uid();
 v_organization uuid;
 v_updated timestamptz;
 v_intake_revision integer;
 v_revision bigint;
 v_key text;
 v_number numeric;
begin
 -- Never trust student or coach IDs supplied by the browser for authorization.
 if v_coach is null or p_student is null
   or not efg_private.coach_has_student(p_student) then
  raise exception 'Not authorized to save this student draft'
    using errcode='42501';
 end if;

 -- Lock the actual intake row before verifying sharing/version. This prevents
 -- simultaneous modifications while saving; publication must recheck separately.
 select intake.organization_id,intake.updated_at,intake.revision
 into v_organization,v_updated,v_intake_revision
 from public.efg_coach_relaunch_intakes intake
 join public.efg_profiles profile on profile.user_id=intake.student_id
 join public.efg_organizations org on org.id=profile.organization_id
 where intake.student_id=p_student
   and profile.active
   and profile.role='student'
   and intake.organization_id=profile.organization_id
   and org.coach_id=v_coach
   and intake.shared_at is not null
   and intake.completed_version='coach_major_2026_r1'
 for update of intake;
 if not exists (
   select 1 from public.efg_pilot_participation_receipts receipt
    join public.efg_consents consent on consent.student_id=receipt.student_id
      and consent.organization_id=receipt.organization_id
   where receipt.student_id=p_student
    and receipt.organization_id=v_organization and receipt.version='coach_pilot_2026_demo1'
    and receipt.participation_accepted and receipt.sharing_accepted
    and receipt.revoked_at is null and consent.accepted
 ) then raise exception 'Pilot sharing permission or coach follow-up consent revoked'
   using errcode='42501'; end if;
 if not found or p_intake_updated_at is null or p_intake_revision is null
   or v_updated is distinct from p_intake_updated_at
   or v_intake_revision is distinct from p_intake_revision then
  raise exception 'Intake not shared or changed; reopen the student intake'
   using errcode='42501';
 end if;

 if pg_catalog.jsonb_typeof(p_goal) is distinct from 'object'
   or pg_catalog.octet_length(p_goal::text)>8000
   or (p_goal->>'goal_type') not in ('fat_loss','recomp','muscle_gain','maintenance')
   then raise exception 'Invalid nutrition goal proposal';
 end if;
 foreach v_key in array array['kcal','protein_g','carb_g','fat_g','fiber_g'] loop
   if pg_catalog.jsonb_typeof(p_goal->v_key) is distinct from 'number' then
     raise exception 'Missing/invalid numeric goal field: %',v_key;
   end if;
   v_number := (p_goal->>v_key)::numeric;
   if v_number < 0 or v_number > (case v_key
     when 'kcal' then 10000 when 'fiber_g' then 150 when 'carb_g' then 2000
     else 1000 end) then
     raise exception 'Goal field outside allowed bounds: %',v_key;
   end if;
 end loop;
 if (p_goal->>'kcal')::numeric < 1200 then
  raise exception 'Kcal below supported estimation range';
 end if;
 if p_guide is not null and (
  pg_catalog.jsonb_typeof(p_guide) is distinct from 'object'
  or pg_catalog.octet_length(p_guide::text)>30000
 ) then
   raise exception 'Invalid guide draft';
 end if;

 -- Versioned optimistic concurrency. A null expected revision only creates a
 -- fresh draft; it does not overwrite another coach tab or a previous save.
 if p_expected_revision is null then
   insert into public.efg_coach_plan_drafts(
     student_id,organization_id,coach_id,source_intake_updated_at,
     source_intake_revision,goal_proposal,guide_proposal
   ) values(p_student,v_organization,v_coach,p_intake_updated_at,v_intake_revision,p_goal,p_guide)
   on conflict (student_id) do nothing
   returning draft_revision into v_revision;
 else
   if p_expected_revision<1 then
     raise exception 'Invalid expected revision';
   end if;
   update public.efg_coach_plan_drafts
   set goal_proposal=p_goal,
       guide_proposal=p_guide,
       source_intake_updated_at=p_intake_updated_at,
       source_intake_revision=v_intake_revision,
       updated_at=now(),
       status='draft',
       draft_revision=draft_revision+1
   where student_id=p_student
     and organization_id=v_organization
     and coach_id=v_coach
     and draft_revision=p_expected_revision
     and status in ('draft','published')
   returning draft_revision into v_revision;
 end if;
 if v_revision is null then
   raise exception 'Draft already exists or version changed; reload before editing'
    using errcode='PT409';
 end if;
 return v_revision;
end;
$function$

CREATE OR REPLACE FUNCTION public.efg_submit_coach_relaunch_intake(p_completed_version text, p_payload jsonb, p_expected_revision integer, p_share_with_coach boolean)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_uid uuid := (select auth.uid());
 v_org uuid;
 v_revision integer;
 v_new_revision integer;
 v_allowed text[] := array[
  'objective','age_years','height_cm','weight_kg','activity_level',
  'dietary_pattern','eating_window','preferred_foods','disliked_foods','meal_routine','notes'
 ];
 v_field text;
 v_text text;
 v_shared timestamptz;
begin
 if v_uid is null then raise exception 'Authentication required' using errcode='42501'; end if;
 if p_completed_version is distinct from 'coach_major_2026_r1' then
  raise exception 'Unsupported Coach relaunch revision' using errcode='22023';
 end if;
 if p_expected_revision is null or p_expected_revision<0 or p_expected_revision>99999
  or p_share_with_coach is null or pg_catalog.jsonb_typeof(p_payload) is distinct from 'object' then
  raise exception 'Invalid intake revision/payload/permission' using errcode='22023';
 end if;
 select p.organization_id into v_org from public.efg_profiles p
  where p.user_id=v_uid and p.role='student' and p.active is true
  and p.organization_id is not null;
 if v_org is null then raise exception 'Active Coach student required' using errcode='42501'; end if;
 -- Participation is required; sharing is a separate OPTIONAL choice checked only when requested.
 if not exists(
  select 1 from public.efg_pilot_participation_receipts r
  where r.student_id=v_uid and r.organization_id=v_org
   and r.version='coach_pilot_2026_demo1' and r.participation_accepted
   and r.revoked_at is null
 ) then
  raise exception 'Current pilot participation required'
   using errcode='42501';
 end if;
 -- Reject unknown and sensitive keys even if a future browser has extra fields.
 for v_field in select pg_catalog.jsonb_object_keys(p_payload) loop
  if not (v_field=any(v_allowed)) then
   raise exception 'Unsupported or sensitive intake field: %',v_field using errcode='22023';
  end if;
 end loop;
 foreach v_field in array v_allowed loop
  if p_payload ? v_field and p_payload->v_field <> 'null'::jsonb then
   if v_field in ('age_years','height_cm','weight_kg') then
    if pg_catalog.jsonb_typeof(p_payload->v_field)<>'number' then
     raise exception 'Numeric intake field type mismatch' using errcode='22023';
    end if;
   elsif pg_catalog.jsonb_typeof(p_payload->v_field)<>'string' then
    raise exception 'Text intake field type mismatch' using errcode='22023';
   end if;
  end if;
 end loop;
 if nullif(p_payload->>'objective','') is not null and
    (p_payload->>'objective') not in ('fat_loss','recomp','muscle_gain','maintenance','general')
  then raise exception 'Invalid objective' using errcode='22023'; end if;
 if nullif(p_payload->>'activity_level','') is not null and
    (p_payload->>'activity_level') not in ('low','light','moderate','high')
  then raise exception 'Invalid activity' using errcode='22023'; end if;
 if nullif(p_payload->>'dietary_pattern','') is not null and
    (p_payload->>'dietary_pattern') not in ('omnivore','mediterranean','dash','vegetarian','vegan','pescatarian','flexitarian','portfolio','low_carb','keto','other')
  then raise exception 'Invalid dietary pattern' using errcode='22023'; end if;
 if nullif(p_payload->>'eating_window','') is not null
    and (p_payload->>'eating_window') not in ('regular','12_12','14_10','16_8')
  then raise exception 'Invalid eating window' using errcode='22023'; end if;
 foreach v_field in array array['preferred_foods','disliked_foods','meal_routine','notes'] loop
  v_text:=coalesce(p_payload->>v_field,'');
  if pg_catalog.char_length(v_text)>(case when v_field='notes' then 1000 else 400 end) then
   raise exception 'Intake free-text too long' using errcode='22023';
  end if;
 end loop;
 if p_payload ? 'age_years' and p_payload->>'age_years' is not null then
  if (p_payload->>'age_years')::numeric not between 18 and 100 or
   (p_payload->>'age_years')::numeric<>pg_catalog.trunc((p_payload->>'age_years')::numeric) then
   raise exception 'Invalid age' using errcode='22023'; end if;
 end if;
 if p_payload ? 'height_cm' and p_payload->>'height_cm' is not null and
   (p_payload->>'height_cm')::numeric not between 100 and 250 then
  raise exception 'Invalid height' using errcode='22023'; end if;
 if p_payload ? 'weight_kg' and p_payload->>'weight_kg' is not null and
   (p_payload->>'weight_kg')::numeric not between 20 and 400 then
  raise exception 'Invalid weight' using errcode='22023'; end if;
 -- NCC: this replacement is the LAST effective definition of the intake RPC.
  -- A shared current Coach nutrition intake must include six core fields;
  -- keeping a draft private, unsharing and clearing remain supported.
  if p_share_with_coach and (
   nullif(p_payload->>'objective','') is null
   or p_payload->>'age_years' is null
   or p_payload->>'height_cm' is null
   or p_payload->>'weight_kg' is null
   or nullif(p_payload->>'activity_level','') is null
   or nullif(p_payload->>'dietary_pattern','') is null
  ) then
   raise exception 'NCC: complete objective, age, height, weight, activity and diet before sharing'
    using errcode='22023';
  end if;
  -- A consenting Coach cannot be inferred from an invitation or an existing plan.
 if p_share_with_coach then
  if not exists(
   select 1 from public.efg_pilot_participation_receipts r
   where r.student_id=v_uid and r.organization_id=v_org
     and r.version='coach_pilot_2026_demo1'
     and r.participation_accepted and r.sharing_accepted and r.revoked_at is null
  ) then
   raise exception 'Separate pilot coach-sharing permission required'
     using errcode='42501';
  end if;
  if not exists(
   select 1 from public.efg_consents c
   where c.student_id=v_uid and c.organization_id=v_org and c.accepted=true
  ) then
   raise exception 'Coach follow-up permission required before sharing intake'
    using errcode='42501';
  end if;
  v_shared:=pg_catalog.now();
 else
  v_shared:=null;
 end if;
 -- Serialize concurrent first submissions and check the expected revision.
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
  v_uid::text||'/'||p_completed_version,0));
 select revision into v_revision from public.efg_coach_relaunch_intakes
  where student_id=v_uid and completed_version=p_completed_version for update;
 if coalesce(v_revision,0)<>p_expected_revision then
  raise exception 'Intake revision conflict; reload before retry' using errcode='PT409';
 end if;
 insert into public.efg_coach_relaunch_intakes(
  student_id,organization_id,completed_version,revision,
  objective,age_years,height_cm,weight_kg,activity_level,dietary_pattern,eating_window,
  preferred_foods,disliked_foods,meal_routine,notes,shared_at,completed_at,updated_at
 ) values(
  v_uid,v_org,p_completed_version,p_expected_revision+1,
  nullif(p_payload->>'objective',''),
  nullif(p_payload->>'age_years','')::integer,
  nullif(p_payload->>'height_cm','')::numeric,
  nullif(p_payload->>'weight_kg','')::numeric,
  nullif(p_payload->>'activity_level',''),
  nullif(p_payload->>'dietary_pattern',''),
  coalesce(nullif(p_payload->>'eating_window',''),'regular'),
  coalesce(p_payload->>'preferred_foods',''),
  coalesce(p_payload->>'disliked_foods',''),
  coalesce(p_payload->>'meal_routine',''),
  coalesce(p_payload->>'notes',''),
  v_shared,pg_catalog.now(),pg_catalog.now()
 )
 on conflict(student_id,completed_version) do update set
  revision=excluded.revision,
  objective=excluded.objective,age_years=excluded.age_years,
  height_cm=excluded.height_cm,weight_kg=excluded.weight_kg,
  activity_level=excluded.activity_level,dietary_pattern=excluded.dietary_pattern,eating_window=excluded.eating_window,
  preferred_foods=excluded.preferred_foods,disliked_foods=excluded.disliked_foods,
  meal_routine=excluded.meal_routine,notes=excluded.notes,
  shared_at=excluded.shared_at,updated_at=excluded.updated_at
 where efg_coach_relaunch_intakes.revision=p_expected_revision
 returning revision into v_new_revision;
 if v_new_revision is null then
  raise exception 'Intake revision conflict' using errcode='PT409';
 end if;
 return v_new_revision;
end
